@Service
public class CatalogImporter {

    private static final int CHUNK = 1_000;
    private final ChunkWriter chunkWriter;

    CatalogImporter(ChunkWriter chunkWriter) {
        this.chunkWriter = chunkWriter;
    }

    public void importProducts(Path csv) throws IOException {
        try (Stream<String> lines = Files.lines(csv)) {
            List<Product> chunk = new ArrayList<>(CHUNK);
            for (Iterator<String> it = lines.skip(1).iterator(); it.hasNext(); ) {
                chunk.add(ProductCsvParser.parse(it.next()));
                if (chunk.size() == CHUNK || !it.hasNext()) {
                    chunkWriter.write(chunk);    // bean khác, có @Transactional
                    chunk.clear();
                }
            }
        }
    }
}

@Component
class ChunkWriter {
    private final ProductRepository productRepository;

    ChunkWriter(ProductRepository productRepository) {
        this.productRepository = productRepository;
    }

    @Transactional
    public void write(List<Product> products) {
        productRepository.saveAll(products);
        // application.yml: spring.jpa.properties.hibernate.jdbc.batch_size: 100
        //                  spring.jpa.properties.hibernate.order_inserts: true
    }
}
